func evensUpTo(limit int) []int {
    evens := make([]int, 0, limit/2)
    for i := 1; i <= limit; i++ {
        if i%2 == 0 {
            evens = append(evens, i)
        }
    }
    return evens
}

func main() {
    evens := evensUpTo(6)
    fmt.Println(evens, len(evens), cap(evens))
}

